func resolveDotGitPath(repoRoot string) (string, error) {
	gitPath := filepath.Join(repoRoot, gitDir)
	info, err := os.Stat(gitPath)
	if err != nil {
		return "", fmt.Errorf("stat .git path: %w", err)
