	}
	if err := s.repo.Storer.SetReference(plumbing.NewHashReference(refName, hash)); err != nil {
		return fmt.Errorf("set checkpoint ref %s to %s: %w", refName, hash, err)
	}
	s.enqueueForPush(ctx, refName)
