	// process CWD in a non-isolated test is just as accidental as the CWD
	// itself.
	if err := ensureTestIsolatedStateDir(commonDir); err != nil {
		return nil, err
	}
	return &StateStore{
		stateDir: filepath.Join(filepath.Clean(commonDir), SessionStateDirName),
	}, nil
}

