// Callers must Close the returned root.
func openSessionStateRoot(ctx context.Context) (*os.Root, error) {
	stateDir, err := getSessionStateDir(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get session state directory: %w", err)
