//
// marker_fallback.go provides the PendingReviewMarker type and its
// write/read/clear helpers, plus RunMarkerFallback which handles review for
// agents that don't (yet) implement AgentReviewer.
//
// For adapter-backed review workers, the new architecture uses env-var
// handshake (env.go) + AgentReviewer.Start, and
// the lifecycle hook reads ENTIRE_REVIEW_* env vars off the spawned
// process — there is no marker-file adoption code path.
//
// For agents without a review-runner adapter, the marker is purely a record of
// what the user was asked to do: RunMarkerFallback writes it before printing manual-start
// guidance, and `entire session attach --review <session-id>` reads the marker
// to tag a manual session after the fact. ReadPendingReviewMarker /
// ClearPendingReviewMarker are exported for that attach flow; nothing else
// reads the marker.
package review

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"time"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
	"github.com/entireio/cli/cmd/entire/cli/session"
)

const pendingReviewMarkerFilename = "review-pending.json"

// PendingReviewMarker is written by `entire review` before instructing the
// user to open an agent manually. The marker records which agent and
// skills should run so that `entire session attach --review` can tag the
// resulting session after the fact.
//
// WorktreePath scopes the marker to the worktree `entire review` was invoked
// from: multiple worktrees in one repo share .git/entire-sessions/, so without
// this field any session in any worktree could race to claim the marker. A
// blank WorktreePath (pre-fix markers) falls back to the legacy unscoped
// behavior — any session can adopt.
type PendingReviewMarker struct {
	AgentName string   `json:"agent_name"`
	Skills    []string `json:"skills"`
	// Prompt is the composed review prompt the agent will receive.
	// Stored on the marker (rather than recomputed on adoption) so session
	// metadata records exactly what the agent was asked to do.
	Prompt       string    `json:"prompt,omitempty"`
	StartingSHA  string    `json:"starting_sha"`
	StartedAt    time.Time `json:"started_at"`
	WorktreePath string    `json:"worktree_path,omitempty"`
}

func pendingMarkerPath(ctx context.Context) (string, error) {
	commonDir, err := session.GetGitCommonDir(ctx)
	if err != nil {
		return "", fmt.Errorf("locate git common dir: %w", err)
	}
	return filepath.Join(commonDir, session.SessionStateDirName, pendingReviewMarkerFilename), nil
}

// WritePendingReviewMarker persists the marker. Overwrites any existing marker.
func WritePendingReviewMarker(ctx context.Context, m PendingReviewMarker) error {
	path, err := pendingMarkerPath(ctx)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
		return fmt.Errorf("create sessions dir: %w", err)
	}
	data, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal marker: %w", err)
	}
	if err := os.WriteFile(path, data, 0o600); err != nil {
		return fmt.Errorf("write marker: %w", err)
	}
	return nil
}

// ReadPendingReviewMarker returns the marker if one exists.
// ok=false with err=nil indicates "no pending review."
func ReadPendingReviewMarker(ctx context.Context) (PendingReviewMarker, bool, error) {
	path, err := pendingMarkerPath(ctx)
	if err != nil {
		return PendingReviewMarker{}, false, err
	}
	data, err := os.ReadFile(path) //nolint:gosec // path derived from git dir
	if errors.Is(err, os.ErrNotExist) {
		return PendingReviewMarker{}, false, nil
	}
	if err != nil {
		return PendingReviewMarker{}, false, fmt.Errorf("read marker: %w", err)
	}
	var m PendingReviewMarker
	if err := json.Unmarshal(data, &m); err != nil {
		return PendingReviewMarker{}, false, fmt.Errorf("parse marker: %w", err)
	}
	return m, true, nil
}

// ClearPendingReviewMarker removes the marker. Missing file is not an error.
func ClearPendingReviewMarker(ctx context.Context) error {
	path, err := pendingMarkerPath(ctx)
	if err != nil {
		return err
	}
	if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("remove marker: %w", err)
	}
	return nil
}

// RunMarkerFallback handles review for agents that do not yet have an Entire
// review-runner adapter by writing the pending-review marker file and printing
// manual-start guidance. The user is told to open the agent themselves and run
// the configured skills.
//
// The marker is NOT auto-adopted by anything — the lifecycle hook reads
// ENTIRE_REVIEW_* env vars on the spawned process, not the marker file.
// For adapterless review agents the user starts the agent manually, so no env
// inheritance happens. The marker exists purely so that `entire session
// attach --review <session-id>` has a record of what the user was asked to
// review when tagging the session after the fact.
//
// agentName must be the agent's registry key (e.g. "cursor").
package investigate

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/provenance"
	"github.com/entireio/cli/cmd/entire/cli/session"
)

// InvestigationsDirName is the directory name (under git common dir) where
// investigation runs persist their per-run artifacts (findings.md +
// state.json).
const InvestigationsDirName = "entire-investigations"

// stateFileName is the on-disk name for the per-run state file inside the
// run directory.
const stateFileName = "state.json"

// runIDPattern is the validation regex for investigation run IDs: exactly
// 12 lowercase hex characters. Shares the checkpoint-id format via
// id.Pattern.
var runIDPattern = regexp.MustCompile("^" + id.Pattern + "$")

// RunState is the persisted state of an investigation run, sufficient to
// resume after a crash, Ctrl+C, or `--continue`.
//
// Round semantics: CompletedRounds counts how many full passes through
// every agent have finished — it is 0 mid-round-1, increments to 1 once
// every agent has had its first turn, and so on. By contrast,
// TurnStance.Round records the 1-indexed round each individual turn
// belongs to. The two fields look similar but represent different things;
// readers must pick the one that matches the question they're asking.
type RunState struct {
	RunID           string       `json:"run_id"`
	Topic           string       `json:"topic"`
	Agents          []string     `json:"agents"`
	MaxTurns        int          `json:"max_turns"`
	Quorum          int          `json:"quorum"`
	CompletedRounds int          `json:"completed_rounds"`
	Turn            int          `json:"turn"`           // overall turn index across rounds
	NextAgentIdx    int          `json:"next_agent_idx"` // index into Agents for the NEXT turn
	Stances         []TurnStance `json:"stances,omitempty"`
	FindingsDoc     string       `json:"findings_doc"` // absolute path
	StartingSHA     string       `json:"starting_sha"`
	StartedAt       time.Time    `json:"started_at"`
	UpdatedAt       time.Time    `json:"updated_at"`

	// PendingTurn is the agent-writable section. After each agent turn the
	// agent sets this to its stance + a short note. The loop reads it
	// after the agent process exits, validates it, appends a TurnStance to
	// Stances[], clears PendingTurn, advances cursors, persists.
	PendingTurn *PendingTurn `json:"pending_turn,omitempty"`
}

// PendingTurn is the agent-written stance for the most recent turn. The
// agent populates this before exiting; the loop reads it, appends to
// Stances[], and clears the field. The `agent` and `turn` fields are
// unambiguous from context (the loop knows which turn it just ran), so the
// agent does not include them.
type PendingTurn struct {
	Stance string `json:"stance"`         // "approve" | "request-changes" | "reject"
	Note   string `json:"note,omitempty"` // short explanation; optional
}

// TurnStance is one agent's recorded stance for a turn.
//
// Round here is the 1-indexed round the turn belongs to (turn 1 of round
// 1, turn N+1 starts round 2, etc.) — distinct from
// RunState.CompletedRounds, which counts finished rounds.
type TurnStance struct {
	Round       int    `json:"round"`
	Turn        int    `json:"turn"` // overall turn number
	Agent       string `json:"agent"`
	Stance      string `json:"stance"` // "approve" | "request-changes" | "reject" | "unknown"
	PlanChanged bool   `json:"plan_changed"`
	Note        string `json:"note,omitempty"`
}

// StateStore is the runs-state directory wrapper. The root contains one
// sub-directory per run (named after the run ID), holding findings.md and
// state.json.
type StateStore struct {
	dir string
}

// NewStateStore creates a StateStore rooted at
// <git-common-dir>/entire-investigations. Resolves the common dir via
// session.GetGitCommonDir, so this requires a git repository context.
func NewStateStore(ctx context.Context) (*StateStore, error) {
	commonDir, err := session.GetGitCommonDir(ctx)
	if err != nil {
		return nil, fmt.Errorf("get git common dir: %w", err)
	}
	return &StateStore{
		dir: filepath.Join(commonDir, InvestigationsDirName),
	}, nil
}

// NewStateStoreWithDir creates a StateStore rooted at dir. Useful for tests
// that don't want to depend on a real git repository.
func NewStateStoreWithDir(dir string) *StateStore {
	return &StateStore{dir: dir}
}

// RunDir returns the absolute path of the per-run directory for runID,
// where findings.md and state.json both live. The directory may or may
// not exist on disk; callers that need it materialised should MkdirAll
// before writing.
//
// Precondition: runID MUST be a validated 12-hex id. RunDir joins it into a
// path that callers feed to os.RemoveAll (via clean), so an unvalidated id
// would be a path-traversal sink. Every path that reaches here enforces this:
// Save/Load validate before calling; manifest List/ResolveByRunID drop
