	os.WriteFile(warnFile, []byte{}, 0o644)
	fmt.Fprintf(w,
		"\nentire: %d ended session(s) are accumulating and slowing down commits.\n"+
			"Run 'entire doctor' to condense them and restore commit performance.\n\n",
		count,
	)
