func TestGetWorktreeID(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name       string
		setupFunc  func(dir string) error
		wantID     string
		wantErr    bool
		errContain string
	}{
		{
			name: "main worktree (git directory)",
			setupFunc: func(dir string) error {
				return os.MkdirAll(filepath.Join(dir, ".git"), 0o755)
			},
			wantID: "",
		},
		{
			name: "ordinary submodule relative gitdir",
			setupFunc: func(dir string) error {
				content := "gitdir: ../../.git/modules/deps/go-git\n"
				return os.WriteFile(filepath.Join(dir, ".git"), []byte(content), 0o644)
			},
			wantID: "",
		},
		{
			name: "ordinary submodule absolute gitdir",
			setupFunc: func(dir string) error {
				content := "gitdir: /repo/.git/modules/deps/go-git\n"
				return os.WriteFile(filepath.Join(dir, ".git"), []byte(content), 0o644)
			},
			wantID: "",
		},
		{
			name: "nested ordinary submodule gitdir",
			setupFunc: func(dir string) error {
				content := "gitdir: /repo/.git/modules/libs/go-git/modules/vendor/crypto\n"
				return os.WriteFile(filepath.Join(dir, ".git"), []byte(content), 0o644)
			},
			wantID: "",
		},
		{
			name: "linked worktree of submodule",
			setupFunc: func(dir string) error {
				content := "gitdir: /repo/.git/modules/deps/go-git/worktrees/sub-linked\n"
				return os.WriteFile(filepath.Join(dir, ".git"), []byte(content), 0o644)
			},
			wantID: "sub-linked",
		},
		{
			name: "ordinary submodule inside linked superproject worktree",
			setupFunc: func(dir string) error {
				content := "gitdir: /repo/.git/worktrees/super-linked/modules/deps/go-git\n"
				return os.WriteFile(filepath.Join(dir, ".git"), []byte(content), 0o644)
			},
			wantID: "",
		},
		{
			name: "linked worktree simple name",
			setupFunc: func(dir string) error {
				content := "gitdir: /some/repo/.git/worktrees/test-wt\n"
				return os.WriteFile(filepath.Join(dir, ".git"), []byte(content), 0o644)
			},
			wantID: "test-wt",
		},
		{
			name: "linked worktree with subdirectory name",
			setupFunc: func(dir string) error {
				content := "gitdir: /repo/.git/worktrees/feature/auth-system\n"
				return os.WriteFile(filepath.Join(dir, ".git"), []byte(content), 0o644)
			},
			wantID: "feature/auth-system",
		},
		{
			name: "no .git exists",
			setupFunc: func(_ string) error {
				return nil // Don't create .git
			},
			wantErr:    true,
			errContain: "failed to stat .git",
		},
		{
			name: "invalid .git file format",
			setupFunc: func(dir string) error {
				return os.WriteFile(filepath.Join(dir, ".git"), []byte("invalid content"), 0o644)
			},
			wantErr:    true,
			errContain: "invalid .git file format",
		},
		{
			name: "bare repo worktree simple name",
			setupFunc: func(dir string) error {
				content := "gitdir: /some/repo/.bare/worktrees/main\n"
				return os.WriteFile(filepath.Join(dir, ".git"), []byte(content), 0o644)
			},
			wantID: "main",
		},
		{
			name: "bare repo worktree with subdirectory name",
			setupFunc: func(dir string) error {
				content := "gitdir: /repo/.bare/worktrees/feature/login\n"
				return os.WriteFile(filepath.Join(dir, ".git"), []byte(content), 0o644)
			},
			wantID: "feature/login",
		},
		{
			name: "gitdir without worktrees path",
			setupFunc: func(dir string) error {
				content := "gitdir: /some/repo/.git\n"
				return os.WriteFile(filepath.Join(dir, ".git"), []byte(content), 0o644)
			},
			wantErr:    true,
			errContain: "unexpected gitdir format",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			dir := t.TempDir()
			if err := tt.setupFunc(dir); err != nil {
				t.Fatalf("setup failed: %v", err)
			}

			id, err := GetWorktreeID(dir)

			if tt.wantErr {
				if err == nil {
					t.Fatalf("GetWorktreeID() error = nil, want error containing %q", tt.errContain)
				}
				if tt.errContain != "" && !strings.Contains(err.Error(), tt.errContain) {
					t.Errorf("GetWorktreeID() error = %v, want error containing %q", err, tt.errContain)
				}
				return
			}

			if err != nil {
				t.Fatalf("GetWorktreeID() error = %v, want nil", err)
			}
			if id != tt.wantID {
				t.Errorf("GetWorktreeID() = %q, want %q", id, tt.wantID)
			}
		})
	}
}

package paths

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// GetWorktreeID returns the internal git worktree identifier for the given path.
// For the main worktree (where .git is a directory), returns empty string.
// For linked worktrees (where .git is a file), extracts the name from
// .git/worktrees/<name>/ path. This name is stable across `git worktree move`.
func GetWorktreeID(worktreePath string) (string, error) {
	gitPath := filepath.Join(worktreePath, ".git")

	info, err := os.Stat(gitPath)
	if err != nil {
		return "", fmt.Errorf("failed to stat .git: %w", err)
	}

	// Main worktree has .git as a directory
	if info.IsDir() {
		return "", nil
	}

	// Linked worktree has .git as a file with content: "gitdir: /path/to/.git/worktrees/<name>"
	content, err := os.ReadFile(gitPath) //nolint:gosec // gitPath is constructed from worktreePath + ".git"
	if err != nil {
		return "", fmt.Errorf("failed to read .git file: %w", err)
	}

	line := strings.TrimSpace(string(content))
	if !strings.HasPrefix(line, "gitdir: ") {
		return "", fmt.Errorf("invalid .git file format: %s", line)
	}

	gitdir := strings.TrimPrefix(line, "gitdir: ")
	if worktreeID, found := parseWorktreeID(gitdir); found {
		return worktreeID, nil
	}

	return "", fmt.Errorf("unexpected gitdir format (no worktrees): %s", gitdir)
}

func parseWorktreeID(gitdir string) (string, bool) {
	gitdir = strings.TrimSuffix(strings.ReplaceAll(gitdir, "\\", "/"), "/")

	// Submodule gitdirs live under .git/modules/<path>. If that submodule
	// repository has its own linked worktree, the gitdir ends with
	// .git/modules/<path>/worktrees/<id>. A /worktrees/ segment before the
	// final /modules/ belongs to the superproject's worktree, not the submodule.
	if modulesIndex := strings.LastIndex(gitdir, "/modules/"); modulesIndex >= 0 {
		afterModules := gitdir[modulesIndex+len("/modules/"):]
		if _, worktreeID, found := strings.Cut(afterModules, "/worktrees/"); found {
			return strings.TrimSuffix(worktreeID, "/"), true
		}
		return "", true
	}

	// Extract worktree name from path like /repo/.git/worktrees/<name>
	// or /repo/.bare/worktrees/<name> (bare repo + worktree layout).
	// The path after the marker is the worktree identifier.
	for _, marker := range []string{".git/worktrees/", ".bare/worktrees/"} {
		if _, worktreeID, found := strings.Cut(gitdir, marker); found {
			return strings.TrimSuffix(worktreeID, "/"), true
		}
	}

	return "", false
}

