func TestCheckpointSummary_HasReview(t *testing.T) {
	t.Parallel()

	// True case: the key must marshal as "has_review": true.
	bTrue, err := json.Marshal(CheckpointSummary{HasReview: true})
	if err != nil {
		t.Fatalf("marshal true: %v", err)
